package com.aistock.market.security;
import com.aistock.common.ApiResponse;import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.servlet.http.Cookie;import org.junit.jupiter.api.Test;import org.springframework.mock.web.*;
import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class MarketHttpSecurityTest {
 @Test void missingCookieAndForgedIdentityCannotAccess()throws Exception{var client=mock(SessionIdentityClient.class);var f=new MarketAccessFilter(client,"service",new ObjectMapper());var q=new MockHttpServletRequest("GET","/api/v1/instruments");q.addHeader("X-User-Id","forged");var r=new MockHttpServletResponse();f.doFilter(q,r,(a,b)->fail());assertEquals(401,r.getStatus());verifyNoInteractions(client);}
 @Test void rejectedSessionAndServiceFailureFailClosed()throws Exception{var c=mock(SessionIdentityClient.class);var f=new MarketAccessFilter(c,"service",new ObjectMapper());var q=new MockHttpServletRequest("GET","/api/v1/instruments/SH600030/daily");q.setCookies(new Cookie("AISTOCK_SESSION","test"));when(c.resolve(any(),anyString())).thenReturn(new ApiResponse<>("AUTH_REQUIRED","denied",null,"trace"));var r=new MockHttpServletResponse();f.doFilter(q,r,(a,b)->fail());assertEquals(401,r.getStatus());reset(c);when(c.resolve(any(),anyString())).thenThrow(new IllegalStateException("down"));r=new MockHttpServletResponse();f.doFilter(q,r,(a,b)->fail());assertEquals(503,r.getStatus());}
 @Test void effectiveSessionPassesOnlyReadMethods()throws Exception{var c=mock(SessionIdentityClient.class);when(c.resolve(any(),anyString())).thenReturn(ApiResponse.success(new SessionIdentityClient.Identity("user","USER",false,1),"t"));var f=new MarketAccessFilter(c,"service",new ObjectMapper());var q=new MockHttpServletRequest("GET","/api/v1/instruments");q.setCookies(new Cookie("AISTOCK_SESSION","test"));var r=new MockHttpServletResponse();boolean[] ok={false};f.doFilter(q,r,(a,b)->ok[0]=true);assertTrue(ok[0]);q.setMethod("POST");r=new MockHttpServletResponse();f.doFilter(q,r,(a,b)->fail());assertEquals(404,r.getStatus());}
}
